package org.duckdns.hjow.swingwebpanel.tls13;

import java.math.BigInteger;
import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.SecureRandom;
import java.security.interfaces.RSAPrivateKey;
import java.security.interfaces.RSAPublicKey;
import java.util.HashMap;
import java.util.Map;
import org.duckdns.hjow.swingwebpanel.tls13.crypto.Bytes;
import org.duckdns.hjow.swingwebpanel.tls13.crypto.EcCurve;
import org.duckdns.hjow.swingwebpanel.tls13.crypto.HashAlg;

/**
 * A key pair for tests that can sign: RSA (generated by the JRE) or EC on a NIST curve (made with the module's own curve arithmetic,
 * because JRE 6 has no EC provider). Signing is implemented here from the definitions, so test certificates and handshake signatures
 * can be produced on JRE 6: RSA PKCS #1 v1.5, RSA-PSS and ECDSA. Keys are cached by name. Example:
 * <code>byte[] sig = TestKey.rsa("server").sign(TestKey.PKCS1, HashAlg.SHA256, data);</code>.
 * <p>
 * 서명할 수 있는 시험용 키 쌍: RSA(JRE 가 생성) 또는 NIST 곡선의 EC(JRE 6 에는 EC 공급자가 없으므로 모듈 자신의 곡선 연산으로 만든다). 서명은 여기서
 * 정의대로 구현하므로 JRE 6 에서 시험 인증서와 핸드셰이크 서명을 만들 수 있다: RSA PKCS #1 v1.5, RSA-PSS, ECDSA. 키는 이름으로 캐시한다.
 */
public final class TestKey {

    /** Signature kind: RSA PKCS #1 v1.5. / 서명 종류: RSA PKCS #1 v1.5. */
    public static final int PKCS1 = 1;

    /** Signature kind: RSA-PSS with a salt of the hash length. / 서명 종류: 해시 길이의 salt 를 쓰는 RSA-PSS. */
    public static final int PSS = 2;

    /** Signature kind: ECDSA. / 서명 종류: ECDSA. */
    public static final int ECDSA = 3;

    /** The cached keys by name. / 이름으로 찾는 캐시된 키. */
    private static final Map<String, TestKey> CACHE = new HashMap<String, TestKey>();

    /** The random source of the test keys. / 시험 키의 난수원. */
    private static final SecureRandom RANDOM = new SecureRandom();

    /** The RSA modulus, or null. / RSA 법. 없으면 null. */
    private BigInteger n;

    /** The RSA public exponent, or null. / RSA 공개 지수. 없으면 null. */
    private BigInteger e;

    /** The RSA private exponent, or null. / RSA 개인 지수. 없으면 null. */
    private BigInteger d;

    /** The PKCS #8 encoding of an RSA private key, or null. / RSA 개인 키의 PKCS #8 부호화. 없으면 null. */
    private byte[] rsaPkcs8;

    /** The curve of an EC key, or null. / EC 키의 곡선. 없으면 null. */
    private EcCurve curve;

    /** The private scalar of an EC key. / EC 키의 개인 스칼라. */
    private BigInteger ecPrivate;

    /** The public point of an EC key. / EC 키의 공개 점. */
    private BigInteger[] ecPublic;

    /**
     * Private constructor; use the factories.
     * <p>
     * 비공개 생성자. 팩터리를 쓴다.
     */
    private TestKey() {
    }

    /**
     * Returns the cached 2048 bit RSA key of a name, generating it on first use.
     * <p>
     * 이름의 캐시된 2048비트 RSA 키를 반환한다. 처음 쓸 때 만든다.
     *
     * @param name the cache name / 캐시 이름
     * @return the key / 키
     */
    public static TestKey rsa(String name) {
        return rsa(name, 2048);
    }

    /**
     * Returns the cached RSA key of a name and size, generating it on first use.
     * <p>
     * 이름과 크기의 캐시된 RSA 키를 반환한다. 처음 쓸 때 만든다.
     *
     * @param name the cache name / 캐시 이름
     * @param bits the modulus length / 법의 길이
     * @return the key / 키
     */
    public static synchronized TestKey rsa(String name, int bits) {
        String id = "rsa-" + bits + "-" + name;
        TestKey k = CACHE.get(id);
        if (k == null) {
            try {
                KeyPairGenerator gen = KeyPairGenerator.getInstance("RSA");
                gen.initialize(bits);
                KeyPair pair = gen.generateKeyPair();
                k = new TestKey();
                k.n = ((RSAPublicKey) pair.getPublic()).getModulus();
                k.e = ((RSAPublicKey) pair.getPublic()).getPublicExponent();
                k.d = ((RSAPrivateKey) pair.getPrivate()).getPrivateExponent();
                k.rsaPkcs8 = pair.getPrivate().getEncoded();
            } catch (java.security.GeneralSecurityException ex) {
                throw new IllegalStateException("cannot generate an RSA key: " + ex);
            }
            CACHE.put(id, k);
        }
        return k;
    }

    /**
     * Returns the cached EC key of a name and curve, generating it on first use.
     * <p>
     * 이름과 곡선의 캐시된 EC 키를 반환한다. 처음 쓸 때 만든다.
     *
     * @param name  the cache name / 캐시 이름
     * @param curve the curve / 곡선
     * @return the key / 키
     */
    public static synchronized TestKey ec(String name, EcCurve curve) {
        String id = "ec-" + curve.name() + "-" + name;
        TestKey k = CACHE.get(id);
        if (k == null) {
            k = new TestKey();
            k.curve = curve;
            k.ecPrivate = scalar(curve);
            k.ecPublic = curve.multiply(k.ecPrivate, curve.base());
            CACHE.put(id, k);
        }
        return k;
    }

    /**
     * Draws a scalar in [1, n - 1].
     * <p>
     * [1, n - 1] 의 스칼라를 뽑는다.
     *
     * @param curve the curve / 곡선
     * @return the scalar / 스칼라
     */
    private static BigInteger scalar(EcCurve curve) {
        // 범위 안의 값이 나올 때까지 다시 뽑는다.
        while (true) {
            BigInteger k = new BigInteger(curve.order().bitLength(), RANDOM);
            if (k.signum() > 0 && k.compareTo(curve.order()) < 0) {
                return k;
            }
        }
    }

    /**
     * Tells if this is an RSA key.
     * <p>
     * RSA 키인지 알려 준다.
     *
     * @return true for RSA / RSA 이면 true
     */
    public boolean isRsa() {
        return n != null;
    }

    /**
     * Returns the curve of an EC key.
     * <p>
     * EC 키의 곡선을 반환한다.
     *
     * @return the curve or null / 곡선 또는 null
     */
    public EcCurve curve() {
        return curve;
    }

    /**
     * Returns the SubjectPublicKeyInfo encoding of the public key.
     * <p>
     * 공개 키의 SubjectPublicKeyInfo 부호화를 반환한다.
     *
     * @return the element / 원소
     */
    public byte[] spki() {
        if (isRsa()) {
            return DerWriter.seq(DerWriter.seq(DerWriter.oid("1.2.840.113549.1.1.1"), DerWriter.nul()),
                    DerWriter.bits(DerWriter.seq(DerWriter.integer(n), DerWriter.integer(e))));
        }
        return DerWriter.seq(DerWriter.seq(DerWriter.oid("1.2.840.10045.2.1"), DerWriter.oid(curveOid())), DerWriter.bits(curve.encodePoint(ecPublic)));
    }

    /**
     * Returns the OID of the curve of an EC key.
     * <p>
     * EC 키 곡선의 OID 를 반환한다.
     *
     * @return the OID / OID
     */
    private String curveOid() {
        return curve == EcCurve.P256 ? "1.2.840.10045.3.1.7" : curve == EcCurve.P384 ? "1.3.132.0.34" : "1.3.132.0.35";
    }

    /**
     * Returns the PKCS #8 encoding of the private key (for a test server that runs in another JVM).
     * <p>
     * 개인 키의 PKCS #8 부호화를 반환한다(다른 JVM 에서 도는 시험 서버용).
     *
     * @return the PrivateKeyInfo element / PrivateKeyInfo 원소
     */
    public byte[] pkcs8() {
        if (isRsa()) {
            return rsaPkcs8.clone();
        }
        byte[] ecPrivateKey = DerWriter.seq(DerWriter.integer(1), DerWriter.octets(EcCurve.toFixed(ecPrivate, curve.fieldBytes())),
                DerWriter.tlv(0xa1, DerWriter.bits(curve.encodePoint(ecPublic))));
        return DerWriter.seq(DerWriter.integer(0), DerWriter.seq(DerWriter.oid("1.2.840.10045.2.1"), DerWriter.oid(curveOid())),
                DerWriter.octets(ecPrivateKey));
    }

    /**
     * Returns the JCA name of the key algorithm.
     * <p>
     * 키 알고리즘의 JCA 이름을 반환한다.
     *
     * @return <code>RSA</code> or <code>EC</code>
     */
    public String algorithm() {
        return isRsa() ? "RSA" : "EC";
    }

    /**
     * Returns the DigestInfo prefix of a hash.
     * <p>
     * 해시의 DigestInfo 접두사를 반환한다.
     *
     * @param hash the hash / 해시
     * @return the prefix / 접두사
     */
    private static byte[] digestInfoPrefix(HashAlg hash) {
        return Hex.decode(hash == HashAlg.SHA256 ? "3031300d060960864801650304020105000420"
                : hash == HashAlg.SHA384 ? "3041300d060960864801650304020205000430" : "3051300d060960864801650304020305000440");
    }

    /**
     * Signs a message.
     * <p>
     * 메시지에 서명한다.
     *
     * @param kind    {@link #PKCS1}, {@link #PSS} or {@link #ECDSA} / 서명 종류
     * @param hash    the hash / 해시
     * @param message the message / 메시지
     * @return the signature (ECDSA: the DER structure of r and s) / 서명(ECDSA 는 r 과 s 의 DER 구조)
     */
    public byte[] sign(int kind, HashAlg hash, byte[] message) {
        byte[] digest = hash.digest(message);
        if (kind == ECDSA) {
            BigInteger order = curve.order();
            BigInteger z = new BigInteger(1, digest);
            int extra = digest.length * 8 - order.bitLength();
            if (extra > 0) {
                z = z.shiftRight(extra);
            }
            // r 과 s 가 0 이 아닌 서명이 나올 때까지 되풀이한다.
            while (true) {
                BigInteger k = scalar(curve);
                BigInteger r = curve.multiply(k, curve.base())[0].mod(order);
                BigInteger s = k.modInverse(order).multiply(z.add(r.multiply(ecPrivate))).mod(order);
                if (r.signum() != 0 && s.signum() != 0) {
                    return DerWriter.seq(DerWriter.integer(r), DerWriter.integer(s));
                }
            }
        }
        int k = (n.bitLength() + 7) / 8;
        byte[] em;
        if (kind == PKCS1) {
            byte[] t = Bytes.concat(digestInfoPrefix(hash), digest);
            em = new byte[k];
            em[1] = 1;
            java.util.Arrays.fill(em, 2, k - t.length - 1, (byte) 0xff);
            System.arraycopy(t, 0, em, k - t.length, t.length);
        } else {
            // RFC 8017 9.1.1 절의 EMSA-PSS 부호화(salt 길이 = 해시 길이).
            int emBits = n.bitLength() - 1;
            int emLen = (emBits + 7) / 8;
            int hLen = hash.length();
            byte[] salt = new byte[hLen];
            RANDOM.nextBytes(salt);
            byte[] h = hash.digest(new byte[8], digest, salt);
            int dbLen = emLen - hLen - 1;
            byte[] db = new byte[dbLen];
            db[dbLen - hLen - 1] = 1;
            System.arraycopy(salt, 0, db, dbLen - hLen, hLen);
            int at = 0;
            // MGF1 마스크로 DB 를 가린다.
            for (int counter = 0; at < dbLen; counter++) {
                byte[] c = new byte[4];
                Bytes.putBe32(counter, c, 0);
                byte[] block = hash.digest(h, c);
                // 마스크 블록을 더한다.
                for (int i = 0; i < block.length && at < dbLen; i++, at++) {
                    db[at] ^= block[i];
                }
            }
            db[0] &= (byte) (0xff >>> (8 * emLen - emBits));
            em = new byte[emLen];
            System.arraycopy(db, 0, em, 0, dbLen);
            System.arraycopy(h, 0, em, dbLen, hLen);
            em[emLen - 1] = (byte) 0xbc;
        }
        return EcCurve.toFixed(new BigInteger(1, em).modPow(d, n), k);
    }
}
